D=CONFIG['hidden_size']; M=CONFIG['intermediate_size']; NL=CONFIG['num_hidden_layers']
S=['mlp.down_proj','mlp.gate_proj','mlp.up_proj','self_attn.k_proj','self_attn.o_proj','self_attn.q_proj','self_attn.v_proj']
